%[text] # Vehicle Speed Reference - Simulation Case
model_name = "HarnessModel_VehSpdRef";
load_system(model_name)

sim_in = Simulink.SimulationInput(model_name);
sim_in = setBlockParameter(sim_in, gcs + "/Vehicle speed reference", ReferencedSubsystem = "VehSpdRef_HighSpeed_refsub");
sim_in = setModelParameter(sim_in, StopTime = "220");
applyToModel(sim_in)

sim_out = sim(sim_in);

sim_data = extractTimetable(sim_out.logsout);

SignalUtil1.plotTimedData( ... %[output:group:1be1a803] %[output:9488dc4a]
  TimedData = sim_data, ... %[output:9488dc4a]
  SignalName = "Vehicle speed reference kph", ... %[output:9488dc4a]
  FigureHeight = 250 ) %[output:group:1be1a803] %[output:9488dc4a]
